import { Badge, Button, Empty, ExportButton, Field, Modal, Panel, Skeleton, TextLink, TrendChart, colors, csvFile, dateLabel, downloadFile, numberLabel } from "./ui";

const navigation = [
  { group: "INSIGHTS", items: [{ id: "overview", title: "개요", icon: LayoutDashboard }, { id: "prompts", title: "프롬프트", icon: MessageCircle }, { id: "competitors", title: "경쟁사 분석", icon: Users }, { id: "sources", title: "인용 출처", icon: Globe2 }, { id: "models", title: "AI 모델", icon: Bot }] },
  { group: "GROWTH", items: [{ id: "personas", title: "고객 페르소나", icon: Compass }, { id: "content", title: "콘텐츠 스튜디오", icon: FileText }, { id: "actions", title: "실행 보드", icon: ListChecks }, { id: "traffic", title: "AI 유입 분석", icon: TrendingUp }, { id: "reports", title: "리포트", icon: BarChart3 }] },
  { group: "WORKSPACE", items: [{ id: "assistant", title: "Lumen 어시스턴트", icon: Sparkles }, { id: "settings", title: "워크스페이스 설정", icon: Settings2 }] },
];
const navItems = navigation.flatMap(g => g.items);
const pageMeta: Record<string, { label: string; title: string; description: string }> = {
  overview: { label: "YOUR BRAND, IN FOCUS", title: "답변 속에서 발견되는 우리 브랜드", description: "AI가 우리 브랜드를 어떻게 소개하는지, 무엇을 바꾸면 좋을지 한눈에 확인하세요." },
  prompts: { label: "FOLLOW THE QUESTIONS", title: "프롬프트", description: "고객이 AI에 묻는 질문을 추적하고, 답변의 원문과 인용 근거를 살펴보세요." },
  competitors: { label: "KNOW YOUR POSITION", title: "경쟁사 분석", description: "동일한 질문에서 우리 브랜드와 경쟁사가 얼마나 자주 등장하는지 비교합니다." },
  sources: { label: "UNDERSTAND THE EVIDENCE", title: "인용 출처", description: "AI 답변이 실제로 참조한 웹사이트에서 콘텐츠 기회를 찾아보세요." },
  models: { label: "EVERY MODEL, ONE VIEW", title: "AI 모델", description: "모델별 수집 상태와 브랜드 가시성을 같은 기준으로 확인합니다." },
  personas: { label: "SEE THROUGH THEIR EYES", title: "고객 페르소나", description: "고객의 상황과 관심사를 정의하고, 그 관점으로 질문을 만들어보세요." },
  content: { label: "TURN INSIGHTS INTO WORDS", title: "콘텐츠 스튜디오", description: "수집된 답변을 바탕으로 검색 의도에 맞는 콘텐츠 초안을 작성합니다." },
  actions: { label: "SMALL STEPS, REAL PROGRESS", title: "실행 보드", description: "발견한 기회를 다음 행동으로 바꾸고, 개선 작업을 끝까지 관리하세요." },
  traffic: { label: "FROM ANSWERS TO VISITS", title: "AI 유입 분석", description: "실제로 우리 웹사이트에 도착한 AI 추천 방문을 확인합니다." },
  reports: { label: "THE STORY BEHIND THE NUMBERS", title: "리포트", description: "수집 결과와 개선 제안을 읽기 쉬운 리포트로 정리하고 공유하세요." },
  assistant: { label: "YOUR THINKING PARTNER", title: "Lumen 어시스턴트", description: "이 워크스페이스의 답변과 지표를 바탕으로 다음 전략을 함께 찾아보세요." },
  settings: { label: "MAKE IT YOURS", title: "워크스페이스 설정", description: "브랜드 정보, 프로젝트, AI 연결 상태를 관리합니다." },
};
const intentNames = { informational: "정보 탐색", comparison: "비교 검토", transactional: "구매 고려" };
const runNames: Record<string, string> = { queued: "대기 중", running: "수집 중", completed: "완료", partial: "일부 완료", failed: "실패" };
const modelName = (model: string) => ({ "gpt-4.1-mini": "GPT-4.1 mini", "gemini-2.5-flash": "Gemini 2.5 Flash", "gemini-3.8-flash": "Gemini 3.8 Flash", "perplexity/sonar": "Perplexity Sonar", "sonar": "Perplexity Sonar", "demo-gemini": "Gemini 샘플", "demo-perplexity": "Perplexity 샘플" }[model] || model);
const subscribeOrigin = () => () => {};
const mobileQuery = "(max-width: 760px)";
const subscribeMobile = (onChange: () => void) => { const media = window.matchMedia(mobileQuery); media.addEventListener("change", onChange); return () => media.removeEventListener("change", onChange); };
const getMobileSnapshot = () => window.matchMedia(mobileQuery).matches;
const sectionPath = (id: string) => id === "overview" ? "/dashboard" : `/dashboard/${id}`;
async function api<T>(path: string, method = "GET", body?: unknown): Promise<T> { const result = await fetch(path, { method, headers: { "Content-Type": "application/json" }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) }); let payload: { error?: string; code?: string }; try { payload = await result.json() as { error?: string; code?: string }; } catch { throw new Error("서버 응답을 읽지 못했어요. 잠시 후 다시 시도해 주세요."); } if (!result.ok) { const error = new Error(payload.error || "요청을 처리하지 못했어요.") as Error & { code?: string }; error.code = payload.code; throw error; } return payload as T; }
function latestAnswers(answers: Answer[], runs: Run[]) { const done = [...runs].filter(r => ["completed", "partial"].includes(r.status)).sort((a, b) => b.createdAt.localeCompare(a.createdAt)); return done.length ? answers.filter(a => a.runId === done[0].id) : answers.filter(a => a.status === "completed"); }
function ownMention(answer: Answer, site: Site) { return answer.mentions.find(m => m.domain.replace(/^www\./, "") === site.domain.replace(/^www\./, "") || m.name.toLowerCase() === site.name.toLowerCase()); }
function Sparkline({ values, color = "#6aa086" }: { values: number[]; color?: string }) { if (!values.length) return null; const max = Math.max(1, ...values); return <svg className="d-metric-spark" viewBox="0 0 70 26" aria-hidden="true"><path d={values.map((v, i) => `${i ? "L" : "M"}${i * 68 / Math.max(1, values.length - 1) + 1},${24 - v / max * 20}`).join(" ")} fill="none" stroke={color} strokeWidth="1.5" strokeLinecap="round" /></svg>; }
function MetricCard({ label, value, suffix, note, hint, icon: Icon, series = [] }: { label: string; value: string; suffix?: string; note: string; hint: string; icon: typeof Target; series?: number[] }) { return <Panel className="d-metric"><div className="d-metric-label">{label}<span title={hint} tabIndex={0} aria-label={hint}><Info size={10} /></span></div><Icon className="d-metric-icon" size={14} strokeWidth={1.5} /><div className="d-metric-value">{value}<small>{suffix}</small></div><div className="d-metric-foot">{note}</div><Sparkline values={series} /></Panel>; }

type FormKind = "site" | "prompt" | "competitor" | "content" | "report" | "task" | "persona";
type EditItem = Site | Prompt | Competitor | Task | Persona;

export default function Dashboard({ user, initialSection = "overview" }: { user: { name: string; email: string }; initialSection?: string }) {
  const section = pageMeta[initialSection] ? initialSection : "overview";
  const [bootstrap, setBootstrap] = useState<Bootstrap | null>(null); const [state, setState] = useState<SiteState | null>(null); const [siteId, setSiteId] = useState(""); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [toast, setToast] = useState("");
  const [mobileNav, setMobileNav] = useState(false); const [commandOpen, setCommandOpen] = useState(false); const [commandText, setCommandText] = useState(""); const [form, setForm] = useState<FormKind | null>(null); const [editItem, setEditItem] = useState<EditItem | null>(null); const [detail, setDetail] = useState<Prompt | null>(null); const [document, setDocument] = useState<SavedDocument | null>(null); const [model, setModel] = useState("all"); const [period, setPeriod] = useState("30"); const [running, setRunning] = useState(false); const [confirmDelete, setConfirmDelete] = useState<{ type: string; id: string; title: string } | null>(null);
  const isMobile = useSyncExternalStore(subscribeMobile, getMobileSnapshot, () => false);
  const sidebarRef = useRef<HTMLElement>(null);
  useEffect(() => { if (mobileNav && isMobile) sidebarRef.current?.querySelector<HTMLAnchorElement>("a")?.focus(); }, [mobileNav, isMobile]);
  const runLock = useRef(false); const currentSite = useRef(siteId); const initialLoad = useRef(false); const [clock] = useState(() => Date.now());
  const chooseSite = useCallback((id: string) => { currentSite.current = id; setSiteId(id); setLoading(Boolean(id)); setError(""); setModel("all"); }, []);
  const flash = useCallback((message: string) => setToast(message), []);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(""), 4000); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { const shortcut = (event: KeyboardEvent) => { if (event.key === "Escape") { setMobileNav(false); } if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(v => !v); } }; window.addEventListener("keydown", shortcut); return () => window.removeEventListener("keydown", shortcut); }, []);
  const refresh = useCallback(async (id = currentSite.current) => { if (!id) return; const next = await api<SiteState>(`/api/sites/${id}/state`); if (currentSite.current === id) setState(next); return next; }, []);
  const refreshBootstrap = useCallback(async () => { const data = await api<Bootstrap>("/api/bootstrap"); setBootstrap(data); return data; }, []);
  useEffect(() => { if (initialLoad.current) return; initialLoad.current = true; (async () => { try { let data = await refreshBootstrap(); let selected: Site | undefined = data.sites.find(s => s.id === localStorage.getItem("lumen-site")) || data.sites[0]; if (new URLSearchParams(location.search).get("demo") === "1") { selected = data.sites.find(s => s.mode === "demo"); if (!selected) { const created = await api<{ site: Site }>("/api/demo", "POST"); selected = created.site; data = await refreshBootstrap(); } history.replaceState({}, "", "/dashboard"); } if (selected) chooseSite(selected.id); else setLoading(false); } catch (e) { setError((e as Error).message); setLoading(false); } })(); }, [refreshBootstrap, chooseSite]);
  useEffect(() => { if (!siteId) return; let active = true; localStorage.setItem("lumen-site", siteId); api<SiteState>(`/api/sites/${siteId}/state`).then(data => { if (active) setState(data); }).catch(e => { if (active) setError(e.message); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [siteId]);
  async function mutate(path: string, method: string, body?: unknown, success?: string) { setBusy(true); setError(""); try { const result = await api(path, method, body); await refresh(); if (success) flash(success); return result; } catch (e) { setError((e as Error).message); throw e; } finally { setBusy(false); } }
  function openForm(kind: FormKind, edit: EditItem | null = null) { setEditItem(edit); setForm(kind); }
  async function createDemo() { setBusy(true); setError(""); try { const result = await api<{ site: Site }>("/api/demo", "POST"); await refreshBootstrap(); chooseSite(result.site.id); flash("샘플 워크스페이스가 준비됐어요"); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  async function submitForm(values: Record<string, unknown>) { const root = `/api/sites/${siteId}`; if (form === "site") { setBusy(true); setError(""); try { const result = await api<{ site: Site }>(editItem ? root : "/api/sites", editItem ? "PATCH" : "POST", values); await refreshBootstrap(); if (editItem) await refresh(); else chooseSite(result.site.id); setForm(null); flash(editItem ? "브랜드 정보를 저장했어요" : "워크스페이스를 만들었어요"); } catch (e) { setError((e as Error).message); throw e; } finally { setBusy(false); } return; }
    const resource = form === "content" || form === "report" ? "documents" : `${form}s`; await mutate(`${root}/${resource}${editItem ? `/${editItem.id}` : ""}`, editItem ? "PATCH" : "POST", form === "content" || form === "report" ? { ...values, kind: form } : values, form === "content" || form === "report" ? "문서를 생성했어요" : "저장했어요"); setForm(null);
  }
  async function processRun(run: Run) { if (runLock.current) return; runLock.current = true; setRunning(true); setError(""); const targetSite = run.siteId; try { let current = run; while (["queued", "running"].includes(current.status)) { try { const response = await api<{ run: Run }>(`/api/sites/${targetSite}/runs/${run.id}/process`, "POST"); current = response.run; await refresh(targetSite); } catch (error) { if ((error as Error & { code?: string }).code !== "run_locked") throw error; await new Promise(resolve => setTimeout(resolve, 2500)); const response = await api<{ run: Run }>(`/api/sites/${targetSite}/runs/${run.id}`); current = response.run; await refresh(targetSite); } } flash(current.status === "completed" ? "답변 수집을 완료했어요" : "수집 결과를 확인해 주세요"); } catch (e) { setError((e as Error).message); } finally { runLock.current = false; setRunning(false); } }
  async function startRun() { if (!state || running) return; if (state.site.mode === "live" && !state.providers.some(p => p.configured && p.available && (model === "all" || p.model === model))) { setError("선택한 AI 모델이 아직 연결되지 않았어요. 워크스페이스 설정에서 제공자 연결 상태를 확인해 주세요."); return; } setBusy(true); setError(""); try { const result = await api<{ run: Run }>(`/api/sites/${siteId}/runs`, "POST", { mode: state.site.mode, models: model !== "all" ? [model] : state.site.mode === "demo" ? [...DEMO_MODELS] : state.providers.filter(p => p.configured && p.available).map(p => p.model) }); await refresh(); setBusy(false); await processRun(result.run); } catch (e) { setError((e as Error).message); setBusy(false); } }
  async function generatePrompts() { try { await mutate(`/api/sites/${siteId}/prompts/generate`, "POST", { count: 5 }, "새 질문 5개를 생성했어요"); } catch {} }
  const cutoff = useMemo(() => period === "all" ? 0 : clock - Number(period) * 86400000, [period, clock]);
  const filteredHistory = useMemo(() => state?.answers.filter(a => (model === "all" || a.model === model) && new Date(a.createdAt).getTime() >= cutoff) || [], [state, model, cutoff]);
  const answers = useMemo(() => state ? latestAnswers(filteredHistory, state.runs.filter(r => filteredHistory.some(a => a.runId === r.id))) : [], [filteredHistory, state]);
  const metrics = useMemo(() => state ? computeMetrics(state.site, state.competitors, answers, state.prompts, filteredHistory) : null, [state, answers, filteredHistory]);
  const activeRun = state?.runs.find(r => ["queued", "running"].includes(r.status)); const meta = pageMeta[section]; const navTitle = navItems.find(n => n.id === section)?.title || "개요";
  async function exportData() { if (!state || !metrics) return; csvFile(`${state.site.name}-${section}-${new Date().toISOString().slice(0, 10)}.csv`, section === "sources" ? [["도메인", "인용 수", "URL"], ...metrics.sources.map(s => [s.domain, s.citations, s.url])] : section === "competitors" ? [["브랜드", "도메인", "언급률(%)", "인용률(%)", "점유율(%)", "평균 등장 순서"], ...metrics.brands.map(b => [b.name, b.domain, b.mentionRate, b.citationRate, b.shareOfVoice, b.averageRank])] : [["질문", "모델", "수집 유형", "상태", "답변", "출처", "수집 시간"], ...filteredHistory.map(a => [a.promptText, a.model, a.mode, a.status, a.text, a.citations.map(c => c.url).join(" | "), a.createdAt])]); flash("현재 필터의 데이터를 내보냈어요"); }
  async function removeConfirmed() { if (!confirmDelete) return; setBusy(true); setError(""); try { if (confirmDelete.type === "site") { await api(`/api/sites/${siteId}`, "DELETE"); const data = await refreshBootstrap(); setState(null); chooseSite(data.sites[0]?.id || ""); } else { await mutate(`/api/sites/${siteId}/${confirmDelete.type}/${confirmDelete.id}`, "DELETE"); } setConfirmDelete(null); flash("삭제했어요"); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  const handleTaskStatus = async (task: Task, status: string) => { try { await mutate(`/api/sites/${siteId}/tasks/${task.id}`, "PATCH", { status }, "작업 상태를 변경했어요"); } catch {} };
  const togglePrompt = async (prompt: Prompt, values: Record<string, boolean>) => { try { await mutate(`/api/sites/${siteId}/prompts/${prompt.id}`, "PATCH", values); } catch {} };
  function navigate(id: string) { setMobileNav(false); window.location.assign(sectionPath(id)); setCommandOpen(false); setCommandText(""); }

  return <div className="d-shell">
    <div className={`d-nav-overlay ${mobileNav ? "open" : ""}`} onClick={() => setMobileNav(false)} />
    <aside ref={sidebarRef} className={`d-sidebar ${mobileNav ? "open" : ""}`} aria-label="주 탐색" inert={isMobile && !mobileNav} aria-hidden={isMobile && !mobileNav ? true : undefined}><a href="/" className="d-brand"><LumenMark />lumen<sup>WORKSPACE</sup></a>
      <div className="d-site-switch"><span className="d-site-avatar">{state?.site.name.slice(0, 1).toUpperCase() || "L"}</span><div style={{ minWidth: 0, flex: 1 }}><label className="d-screen-reader" htmlFor="site-switcher">워크스페이스 선택</label><select id="site-switcher" value={siteId} onChange={e => { if (e.target.value === "new") openForm("site"); else chooseSite(e.target.value); }}><option value="" disabled>워크스페이스 선택</option>{bootstrap?.sites.map(s => <option key={s.id} value={s.id}>{s.name}{s.mode === "demo" ? " (샘플)" : ""}</option>)}<option value="new">+ 새 워크스페이스</option></select><small>{state?.site.mode === "demo" ? "샘플 워크스페이스" : "브랜드 워크스페이스"}</small></div></div>
      <button className="d-search-trigger" onClick={() => setCommandOpen(true)}><Search size={13} />빠른 검색<kbd>⌘ K</kbd></button>
      <nav className="d-nav">{navigation.map(group => <div className="d-nav-group" key={group.group}><div className="d-nav-label">{group.group}</div>{group.items.map(item => <a key={item.id} href={sectionPath(item.id)} onClick={() => setMobileNav(false)} className={`d-nav-link ${section === item.id ? "active" : ""}`} aria-current={section === item.id ? "page" : undefined}><item.icon />{item.title}{item.id === "assistant" && <span className="d-nav-tag">AI</span>}</a>)}</div>)}</nav>
      <div className="d-sidebar-bottom"><div className="d-workspace-note"><strong>발견에서, 다음 행동까지.</strong><p>브랜드를 더 잘 설명하는 콘텐츠가<br />더 좋은 답변을 만듭니다.</p><button onClick={() => navigate("assistant")}>어시스턴트와 살펴보기<ArrowUpRight size={12} /></button></div><div className="d-profile"><span className="d-profile-avatar">{user.name.slice(0, 1).toUpperCase()}</span><div><strong>{user.name}</strong><small>개인 워크스페이스</small></div><a href="/signout-with-chatgpt?return_to=%2F" aria-label="로그아웃"><LogOut size={13} /></a></div></div>
    </aside>
    <div className="d-main"><header className="d-topbar"><button className="d-icon-button d-mobile-menu" onClick={() => setMobileNav(true)} aria-label="메뉴 열기"><Menu size={19} /></button><span>워크스페이스</span><ChevronRight size={11} /><span className="d-topbar-current">{navTitle}</span><div className="d-topbar-end"><span className="d-live-indicator"><span className="d-live-dot" />{state?.site.mode === "demo" ? "샘플 데이터" : "워크스페이스 연결됨"}</span><button className="d-icon-button" aria-label="워크스페이스 새로고침" onClick={() => refresh().catch(e => setError(e.message))}><RefreshCw size={15} /></button><button className="d-icon-button" aria-label="도움말" onClick={() => { navigate("assistant"); }}><CircleHelp size={16} /></button><span className="d-profile-avatar">{user.name.slice(0, 1).toUpperCase()}</span></div></header>
      <main className="d-content">
        {error && <div className="d-error" role="alert"><Info size={15} /><span>{error}</span><button className="d-icon-button" onClick={() => setError("")} aria-label="오류 메시지 닫기"><X size={14} /></button></div>}
        {loading ? <Skeleton /> : !state ? <div className="d-onboard"><div className="d-onboard-eyebrow"><Sparkles size={13} /> A CLEARER PICTURE STARTS HERE</div><h1>AI가 말하는 우리 브랜드,<br />이제 직접 확인하세요.</h1><p>고객의 질문부터 AI의 답변, 다음 콘텐츠까지.<br />브랜드의 발견 가능성을 키우는 워크스페이스를 만들어보세요.</p><div className="d-onboard-grid"><Panel className="d-onboard-card"><Globe2 size={28} strokeWidth={1.3} /><h2>내 브랜드로 시작하기</h2><p>브랜드와 웹사이트를 등록하고<br />실제 AI 답변 수집을 시작합니다.</p><Button variant="primary" onClick={() => openForm("site")}><Plus size={14} />워크스페이스 만들기</Button></Panel><Panel className="d-onboard-card"><PanelTop size={28} strokeWidth={1.3} /><h2>먼저 둘러보기</h2><p>별도의 샘플 데이터로 Lumen의<br />분석 기능과 작업 흐름을 경험하세요.</p><Button onClick={createDemo} busy={busy}>샘플 워크스페이스 열기<ArrowRight size={14} /></Button></Panel></div><div className="d-onboard-features"><span><Check size={12} />답변 원문과 인용 출처</span><span><Check size={12} />경쟁 브랜드 비교</span><span><Check size={12} />콘텐츠와 실행 관리</span></div></div> : <>
          <div className="d-page-title"><div><div className="d-eyebrow">{meta.label}</div><h1>{meta.title}</h1><p>{meta.description}</p></div><div className="d-page-actions">{["overview", "prompts", "competitors", "sources", "models"].includes(section) && <ExportButton onClick={exportData} />}{["overview", "models"].includes(section) && <Button variant="primary" onClick={startRun} busy={busy || running} disabled={!state.prompts.some(p => p.active)}><RefreshCw size={13} />{state.site.mode === "demo" ? "샘플 분석 실행" : "답변 수집"}</Button>}{section === "prompts" && <Button variant="primary" onClick={() => openForm("prompt")}><Plus size={14} />질문 추가</Button>}{section === "competitors" && <Button variant="primary" onClick={() => openForm("competitor")}><Plus size={14} />경쟁사 추가</Button>}{section === "personas" && <Button variant="primary" onClick={() => openForm("persona")}><Plus size={14} />페르소나 추가</Button>}{section === "content" && <Button variant="primary" onClick={() => openForm("content")}><Sparkles size={14} />콘텐츠 만들기</Button>}{section === "reports" && <Button variant="primary" onClick={() => openForm("report")}><Plus size={14} />리포트 생성</Button>}{section === "actions" && <Button variant="primary" onClick={() => openForm("task")}><Plus size={14} />작업 추가</Button>}{section === "settings" && <Button variant="primary" onClick={() => openForm("site")}><Plus size={14} />워크스페이스 추가</Button>}</div></div>
          {state.site.mode === "demo" && <div className="d-demo-banner"><Info size={13} /><span>샘플 워크스페이스입니다. 지표, AI 답변, 콘텐츠는 제품 체험을 위한 예시입니다.</span><button onClick={() => openForm("site")}>내 브랜드 연결</button></div>}
          {state.dataWindow?.truncated && <div className="d-demo-banner"><Info size={13} /><span>최근 30일 답변 {numberLabel(state.dataWindow.totalAnswers)}개 중 최신 {numberLabel(state.dataWindow.answersReturned)}개를 표시합니다. 추이와 내보내기는 화면에 로드된 근거 기준입니다.</span><a href={`/api/sites/${siteId}/export`} className="d-text-link">전체 30일 CSV<ArrowDownToLine size={12} /></a></div>}
          {activeRun && <div className="d-run-progress"><Radio size={20} className={running ? "d-spin" : ""} /><div><strong>{running ? "답변을 수집하고 있어요" : "진행 중인 수집이 있어요"}</strong><p>{activeRun.completed}개 완료{activeRun.failed ? `, ${activeRun.failed}개 실패` : ""} / 전체 {activeRun.total}개. 화면을 닫아도 완료한 답변은 저장됩니다.</p><div className="d-progress-track"><div className="d-progress-fill" style={{ width: `${(activeRun.completed + activeRun.failed) / Math.max(1, activeRun.total) * 100}%` }} /></div></div>{!running && <Button onClick={() => processRun(activeRun)}><Play size={12} />이어서 수집</Button>}</div>}
          {["overview", "prompts", "competitors", "sources", "models"].includes(section) && <div className="d-filterbar"><label className="d-select-wrap"><CalendarDays size={13} /><select aria-label="분석 기간" value={period} onChange={e => setPeriod(e.target.value)}><option value="7">최근 7일</option><option value="30">최근 30일</option></select></label><label className="d-select-wrap"><Bot size={13} /><select aria-label="AI 모델 필터" value={model} onChange={e => setModel(e.target.value)}><option value="all">모든 AI 모델</option>{Array.from(new Set([...(state.site.mode === "demo" ? DEMO_MODELS : state.providers.map(p => p.model)), ...state.answers.map(a => a.model)])).map(m => { const unavailable = state.site.mode !== "demo" && !state.providers.some(p => p.model === m && p.configured && p.available) && !state.answers.some(a => a.model === m); return <option key={m} value={m} disabled={unavailable}>{modelName(m)}{unavailable ? " (연결 필요)" : ""}</option>; })}</select></label><span className="d-filter-note"><RefreshCw size={10} />{state.runs[0]?.createdAt ? `${dateLabel(state.runs[0].createdAt)} 수집 기준` : "아직 수집된 답변이 없습니다"}</span></div>}
          {metrics && section === "overview" && <Overview state={state} metrics={metrics} answers={answers} navigate={navigate} openPrompt={setDetail} openForm={openForm} />}
          {metrics && section === "prompts" && <Prompts state={state} answers={answers} busy={busy || running} onDetail={setDetail} onEdit={p => openForm("prompt", p)} onDelete={p => setConfirmDelete({ type: "prompts", id: p.id, title: p.text })} onToggle={togglePrompt} onGenerate={generatePrompts} onRun={startRun} />}
          {metrics && section === "competitors" && <Competitors state={state} metrics={metrics} onEdit={c => openForm("competitor", c)} onDelete={c => setConfirmDelete({ type: "competitors", id: c.id, title: c.name })} onAdd={() => openForm("competitor")} />}
          {metrics && section === "sources" && <Sources metrics={metrics} />}
          {metrics && section === "models" && <Models state={state} answers={filteredHistory} />}
          {section === "personas" && <Personas state={state} onAdd={() => openForm("persona")} onDelete={p => setConfirmDelete({ type: "personas", id: p.id, title: p.name })} onUse={async p => { try { await mutate(`/api/sites/${siteId}/prompts/generate`, "POST", { personaId: p.id, count: 3 }, "페르소나 관점의 질문 3개를 생성했어요"); navigate("prompts"); } catch {} }} busy={busy} />}
          {(section === "content" || section === "reports") && <Documents documents={state.documents.filter(d => d.kind === (section === "content" ? "content" : "report"))} kind={section === "content" ? "content" : "report"} onOpen={setDocument} onCreate={() => openForm(section === "content" ? "content" : "report")} />}
          {section === "actions" && <Actions tasks={state.tasks} onEdit={t => openForm("task", t)} onStatus={handleTaskStatus} onDelete={t => setConfirmDelete({ type: "tasks", id: t.id, title: t.title })} onAdd={() => openForm("task")} />}
          {section === "traffic" && <Traffic state={state} flash={flash} />}
          {section === "settings" && <Settings state={state} user={user} onEdit={() => openForm("site", state.site)} onDelete={() => setConfirmDelete({ type: "site", id: siteId, title: state.site.name })} />}
          {section === "assistant" && <Assistant key={siteId} siteId={siteId} siteName={state.site.name} demo={state.site.mode === "demo"} />}
          <footer className="d-feedback">Lumen Workspace<span style={{ float: "right" }}>더 명확한 답변. 더 나은 다음 행동.</span></footer>
        </>}
      </main>
    </div>
    {toast && <div className="d-toast" role="status"><CheckCircle2 size={15} />{toast}</div>}
    {form && <ProductForm kind={form} edit={editItem} busy={busy} onClose={() => setForm(null)} onSubmit={submitForm} demo={state?.site.mode === "demo"} />}
    {detail && state && <PromptDetail prompt={detail} state={state} onClose={() => setDetail(null)} />}
    {document && <DocumentEditor document={document} onClose={() => setDocument(null)} onSave={async content => { await mutate(`/api/sites/${siteId}/documents/${document.id}`, "PATCH", { content }, "문서를 저장했어요"); setDocument({ ...document, content }); }} />}
    {confirmDelete && <Modal title="삭제하시겠어요?" subtitle={`‘${confirmDelete.title.slice(0, 60)}’${confirmDelete.type === "site" ? " 워크스페이스와 연결된 데이터를" : " 항목을"} 삭제합니다. 이 작업은 되돌릴 수 없습니다.`} onClose={() => setConfirmDelete(null)}><div className="d-form"><div className="d-form-actions"><Button onClick={() => setConfirmDelete(null)}>취소</Button><Button variant="danger" busy={busy} onClick={removeConfirmed}>삭제하기</Button></div></div></Modal>}
    {commandOpen && <Modal title="빠른 검색" onClose={() => setCommandOpen(false)}><div className="d-command"><input className="d-search-input" value={commandText} onChange={e => setCommandText(e.target.value)} placeholder="페이지나 질문을 검색하세요…" aria-label="페이지나 질문 검색" autoFocus />{navItems.filter(item => item.title.includes(commandText)).map(item => <button className="d-command-result" key={item.id} onClick={() => navigate(item.id)}><item.icon size={16} />{item.title}<small>페이지로 이동 ↵</small></button>)}{commandText && state?.prompts.filter(p => p.text.includes(commandText)).slice(0, 5).map(p => <button className="d-command-result" key={p.id} onClick={() => { setCommandOpen(false); setDetail(p); }}><MessageCircle size={15} />{p.text.slice(0, 65)}</button>)}</div></Modal>}
  </div>;
}

function LumenMark() { return <svg width="27" height="29" viewBox="0 0 28 28" fill="none" aria-hidden="true"><path d="M12 1h4v9.2l6.5-6.5 2.8 2.8-6.5 6.5H28v4h-9.2l6.5 6.5-2.8 2.8-6.5-6.5V29h-4v-9.2l-6.5 6.5-2.8-2.8 6.5-6.5H0v-4h9.2L2.7 6.5l2.8-2.8 6.5 6.5V1Z" fill="currentColor" /></svg>; }

function Overview({ state, metrics, answers, navigate, openPrompt, openForm }: { state: SiteState; metrics: Metrics; answers: Answer[]; navigate: (id: string) => void; openPrompt: (p: Prompt) => void; openForm: (k: FormKind) => void }) {
  const has = metrics.answerCount > 0; const ranked = [...metrics.brands].sort((a, b) => b.shareOfVoice - a.shareOfVoice); const recentPrompts = [...state.prompts].sort((a, b) => Number(b.pinned) - Number(a.pinned)).slice(0, 5);
  return <><div className="d-grid-4"><MetricCard label="브랜드 언급률" value={has ? numberLabel(metrics.mentionRate) : "—"} suffix={has ? "%" : ""} note={`${metrics.answerCount}개 답변 기준`} hint="완료된 답변 중 브랜드나 도메인이 한 번 이상 언급된 답변의 비율입니다." icon={Target} series={metrics.series.map(s => s.mentionRate)} /><MetricCard label="답변 내 점유율" value={has ? numberLabel(metrics.shareOfVoice) : "—"} suffix={has ? "%" : ""} note={`등록 브랜드 ${metrics.brands.length}개 비교`} hint="우리 브랜드와 등록 경쟁사의 총 언급 중 우리 브랜드가 차지하는 비율입니다." icon={BarChart3} /><MetricCard label="브랜드 인용률" value={has ? numberLabel(metrics.citationRate) : "—"} suffix={has ? "%" : ""} note="제공자가 표시한 인용 출처 기준" hint="완료된 전체 답변 중 우리 도메인을 출처로 인용한 답변의 비율입니다. 본문의 일반 링크는 제외합니다. 인용을 제공하지 않는 일반 생성 모델도 분모에 포함되므로, 같은 수집 방식의 모델끼리 비교하세요." icon={Globe2} series={metrics.series.map(s => s.citationRate)} /><MetricCard label="평균 등장 순서" value={metrics.averageRank === null ? "—" : numberLabel(metrics.averageRank)} suffix={metrics.averageRank === null ? "" : "번째"} note="브랜드가 등장한 답변만 집계" hint="답변에 등장한 추적 브랜드의 첫 등장 순서 평균이며 검색 순위가 아닙니다." icon={TrendingUp} /></div>
    <div className="d-overview-middle"><Panel title="브랜드 가시성 추이" subtitle="AI 답변에서 우리 브랜드가 언급된 비율" action={<Badge tone="green"><span className="d-live-dot" />{state.site.name}</Badge>}>{has ? <><div className="d-chart-summary"><strong>{numberLabel(metrics.mentionRate)}<small>%</small></strong><small>최근 완료 수집 기준</small></div><TrendChart data={metrics.series.map(s => ({ date: s.date, value: s.mentionRate }))} /><div className="d-chart-legend"><span><i className="d-legend-dot" style={{ background: "#157c70" }} />{state.site.name}</span><span>날짜별 완료 답변 기준</span></div></> : <Empty title="첫 번째 답변을 기다리고 있어요" text="질문을 추가하고 답변을 수집하면 브랜드의 가시성 추이가 나타납니다." action={<Button onClick={() => navigate("prompts")}>질문 관리하기<ArrowRight size={13} /></Button>} />}</Panel><Panel title="경쟁 브랜드 점유율" subtitle="추적 중인 브랜드의 답변 내 비중" action={<button className="d-icon-button" aria-label="경쟁사 분석 열기" onClick={() => navigate("competitors")}><MoreHorizontal size={16} /></button>}><div className="d-brand-ranking">{ranked.slice(0, 5).map((brand, index) => <div className="d-ranking-row" key={brand.domain}><span className="d-ranking-number">{index + 1}</span><span className="d-ranking-logo" style={{ color: colors[index % colors.length] }}>{brand.name.slice(0, 1)}</span><div className="d-ranking-details"><div className="d-ranking-name"><strong>{brand.name}</strong>{brand.isOwn && <small>우리 브랜드</small>}</div><div className="d-progress-track"><div className="d-progress-fill" style={{ width: `${brand.shareOfVoice}%`, background: colors[index % colors.length] }} /></div></div><span className="d-ranking-value">{has ? `${numberLabel(brand.shareOfVoice)}%` : "—"}</span></div>)}</div><div className="d-ranking-foot"><Info size={10} />전체 AI 시장 점유율이 아닌, 등록 브랜드 간 비교입니다.</div></Panel></div>
    <div className="d-overview-bottom"><Panel title="추적 중인 질문" subtitle="고객의 질문에서 브랜드의 기회를 발견하세요" action={<TextLink onClick={() => navigate("prompts")}>전체 보기</TextLink>}>{recentPrompts.length ? <><div className="d-table-wrap"><table className="d-table"><thead><tr><th>질문</th><th>검색 의도</th><th>언급률</th><th /></tr></thead><tbody>{recentPrompts.map(prompt => { const rows = answers.filter(a => a.promptId === prompt.id && a.status === "completed"); const mentions = rows.filter(a => ownMention(a, state.site)?.mentioned).length; return <tr key={prompt.id}><td className="d-td-title"><button className="d-table-title" onClick={() => openPrompt(prompt)}>{prompt.text}</button><div className="d-table-sub">{prompt.topic || "일반"}</div></td><td><Badge tone={prompt.intent === "comparison" ? "purple" : prompt.intent === "transactional" ? "amber" : "gray"}>{intentNames[prompt.intent]}</Badge></td><td>{rows.length ? `${numberLabel(mentions / rows.length * 100)}%` : "—"}</td><td><button className="d-icon-button" aria-label="답변 보기" onClick={() => openPrompt(prompt)}><ChevronRight size={13} /></button></td></tr>; })}</tbody></table></div><div className="d-table-footer"><span>총 {state.prompts.length}개 질문 · 활성 {state.prompts.filter(p => p.active).length}개</span><span>수집 커버리지 {numberLabel(metrics.coverage)}%</span></div></> : <Empty title="어떤 질문에서 발견되고 싶나요?" text="고객이 제품을 찾거나 비교할 때 묻는 질문을 등록해 보세요." action={<Button onClick={() => openForm("prompt")}><Plus size={12} />첫 질문 추가</Button>} />}</Panel><Panel title="다음 행동" subtitle="인사이트를 작은 실행으로 바꾸세요" action={<TextLink onClick={() => navigate("actions")}>보드 보기</TextLink>}><div className="d-activity-list">{state.tasks.filter(t => t.status !== "done").slice(0, 3).map(task => <div className="d-activity" key={task.id}><span className="d-activity-icon"><ListChecks size={13} /></span><div><strong>{task.title}</strong><p>{task.description.slice(0, 80)}</p></div></div>)}{!state.tasks.some(t => t.status !== "done") && <div className="d-activity"><span className="d-activity-icon"><Sparkles size={13} /></span><div><strong>{has ? "답변에서 콘텐츠 기회 찾기" : "브랜드의 첫 질문 등록하기"}</strong><p>{has ? "자주 언급되는 주제와 인용 출처를 살펴보고, 다음 콘텐츠 작업을 만들어 보세요." : "우리 제품을 필요로 하는 고객의 상황을 떠올리며 질문을 작성해 보세요."}</p></div></div>}<div className="d-activity"><span className="d-activity-icon"><Globe2 size={13} /></span><div><strong>실제 근거에서 시작하세요</strong><p>언급률만으로 성과를 단정하지 말고, 답변의 맥락과 인용된 콘텐츠를 함께 확인하세요.</p></div></div></div><div className="d-ranking-foot"><TextLink onClick={() => navigate("assistant")}><Sparkles size={11} />어시스턴트와 기회 살펴보기</TextLink></div></Panel></div>
  </>;
}

function Prompts({ state, answers, busy, onDetail, onEdit, onDelete, onToggle, onGenerate, onRun }: { state: SiteState; answers: Answer[]; busy: boolean; onDetail: (p: Prompt) => void; onEdit: (p: Prompt) => void; onDelete: (p: Prompt) => void; onToggle: (p: Prompt, values: Record<string, boolean>) => void; onGenerate: () => void; onRun: () => void }) {
  const [query, setQuery] = useState(""); const [intent, setIntent] = useState("all"); const [onlyPinned, setOnlyPinned] = useState(false); const [page, setPage] = useState(0);
  const prompts = state.prompts.filter(p => (!query || `${p.text} ${p.topic}`.toLowerCase().includes(query.toLowerCase())) && (intent === "all" || p.intent === intent) && (!onlyPinned || p.pinned)).sort((a, b) => Number(b.pinned) - Number(a.pinned));
  return <><Panel><div className="d-toolbar"><div className="d-search-box"><Search size={13} /><input className="d-search-input" placeholder="질문 또는 주제 검색" aria-label="질문 검색" value={query} onChange={e => { setQuery(e.target.value); setPage(0); }} /></div><label className="d-select-wrap"><Filter size={12} /><select aria-label="검색 의도" value={intent} onChange={e => { setIntent(e.target.value); setPage(0); }}><option value="all">모든 의도</option>{Object.entries(intentNames).map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select></label><Button variant={onlyPinned ? "primary" : "default"} onClick={() => { setOnlyPinned(v => !v); setPage(0); }} aria-pressed={onlyPinned}><Pin size={12} />고정</Button><Button onClick={onGenerate} busy={busy}><WandSparkles size={13} />AI 질문 제안</Button><Button variant="primary" onClick={onRun} busy={busy} disabled={!state.prompts.some(p => p.active)}><Play size={12} />수집</Button></div>{prompts.length ? <><div className="d-table-wrap"><table className="d-table"><thead><tr><th style={{ width: 40 }}>추적</th><th>질문</th><th>주제 / 의도</th><th>언급률</th><th>답변 수</th><th /></tr></thead><tbody>{prompts.slice(page * 10, page * 10 + 10).map(prompt => { const rows = answers.filter(a => a.promptId === prompt.id && a.status === "completed"); return <tr key={prompt.id}><td><input type="checkbox" className="d-prompt-check" aria-label={`${prompt.text} 추적 활성화`} checked={prompt.active} onChange={e => onToggle(prompt, { active: e.target.checked })} disabled={busy} /></td><td className="d-td-title"><button className="d-table-title" onClick={() => onDetail(prompt)}>{prompt.text}</button><div className="d-table-sub">{dateLabel(prompt.createdAt)} 추가</div></td><td><div style={{ marginBottom: 5, fontSize: 10 }}>{prompt.topic || "일반"}</div><Badge tone={prompt.intent === "comparison" ? "purple" : "gray"}>{intentNames[prompt.intent]}</Badge></td><td>{rows.length ? `${numberLabel(rows.filter(a => ownMention(a, state.site)?.mentioned).length / rows.length * 100)}%` : "—"}</td><td>{rows.length}</td><td><div className="d-table-actions"><button className={`d-icon-button ${prompt.pinned ? "active" : ""}`} aria-label={prompt.pinned ? "질문 고정 해제" : "질문 고정"} onClick={() => onToggle(prompt, { pinned: !prompt.pinned })}><Pin size={13} /></button><button className="d-icon-button" onClick={() => onEdit(prompt)} aria-label="질문 편집"><Pencil size={13} /></button><button className="d-icon-button" onClick={() => onDelete(prompt)} aria-label="질문 삭제"><Trash2 size={13} /></button></div></td></tr>; })}</tbody></table></div><div className="d-table-footer"><span>{prompts.length}개 질문 중 {page * 10 + 1}–{Math.min(page * 10 + 10, prompts.length)}</span><div className="d-row-inline"><Button disabled={!page} onClick={() => setPage(p => p - 1)}>이전</Button><Button disabled={(page + 1) * 10 >= prompts.length} onClick={() => setPage(p => p + 1)}>다음</Button></div></div></> : <Empty title={state.prompts.length ? "검색 결과가 없어요" : "첫 번째 질문을 등록해 보세요"} text={state.prompts.length ? "검색어나 필터를 바꿔서 다시 찾아보세요." : "직접 질문을 작성하거나 AI의 제안으로 시작할 수 있어요."} />}</Panel><RunHistory runs={state.runs} /></>;
}

function RunHistory({ runs }: { runs: Run[] }) { return <Panel className="d-section-space" title="수집 기록" subtitle="수집 실패와 진행 상태까지 기록합니다">{runs.length ? <div className="d-table-wrap"><table className="d-table"><thead><tr><th>시작 시간</th><th>모델</th><th>유형</th><th>수집 결과</th><th>상태</th></tr></thead><tbody>{runs.slice(0, 8).map(run => <tr key={run.id}><td>{new Date(run.createdAt).toLocaleString("ko-KR")}</td><td>{run.models.map(modelName).join(", ")}</td><td><Badge>{run.mode === "demo" ? "샘플" : "실제 API"}</Badge></td><td>{run.completed} / {run.total}{run.failed > 0 ? ` (${run.failed}개 실패)` : ""}</td><td><Badge tone={run.status === "completed" ? "green" : run.status === "failed" ? "amber" : "gray"}>{runNames[run.status]}</Badge>{run.error && <p className="d-table-sub" style={{ maxWidth: 220, whiteSpace: "normal" }}>{run.error}</p>}</td></tr>)}</tbody></table></div> : <Empty title="아직 수집 기록이 없어요" text="질문을 등록한 뒤 수집을 실행하면 기록이 나타납니다." />}</Panel>; }

function Competitors({ state, metrics, onEdit, onDelete, onAdd }: { state: SiteState; metrics: Metrics; onEdit: (c: Competitor) => void; onDelete: (c: Competitor) => void; onAdd: () => void }) { const brands = [...metrics.brands].sort((a, b) => b.mentionRate - a.mentionRate); return <><div className="d-rich-note"><Info size={15} /><span>등록된 브랜드 목록으로 저장된 답변을 다시 평가합니다. 경쟁사를 변경하면 과거 점유율도 달라질 수 있으며, 시장 전체의 점유율을 뜻하지 않습니다.</span></div><Panel title="브랜드 비교" subtitle={`${metrics.answerCount}개 완료 답변에서 같은 기준으로 비교합니다`}><div className="d-table-wrap"><table className="d-table"><thead><tr><th>브랜드</th><th>언급률</th><th>답변 내 점유율</th><th>인용률</th><th>평균 등장 순서</th><th /></tr></thead><tbody>{brands.map((brand, i) => { const competitor = state.competitors.find(c => c.domain === brand.domain); return <tr key={brand.domain}><td><div className="d-row-inline"><span className="d-ranking-logo" style={{ color: colors[i % colors.length] }}>{brand.name[0]}</span><div>{brand.name}{brand.isOwn && <Badge tone="green">우리 브랜드</Badge>}<div className="d-table-sub">{brand.domain}</div></div></div></td><td><div className="d-row-inline"><div className="d-progress-track" style={{ width: 66 }}><div className="d-progress-fill" style={{ width: `${brand.mentionRate}%`, background: colors[i % colors.length] }} /></div>{numberLabel(brand.mentionRate)}%</div></td><td>{numberLabel(brand.shareOfVoice)}%</td><td>{numberLabel(brand.citationRate)}%</td><td>{brand.averageRank === null ? "—" : `${numberLabel(brand.averageRank)}번째`}</td><td>{competitor && <div className="d-table-actions"><button aria-label="경쟁사 편집" className="d-icon-button" onClick={() => onEdit(competitor)}><Pencil size={13} /></button><button aria-label="경쟁사 삭제" className="d-icon-button" onClick={() => onDelete(competitor)}><Trash2 size={13} /></button></div>}</td></tr>; })}</tbody></table></div>{!state.competitors.length && <Empty title="함께 비교할 브랜드를 등록하세요" text="고객이 우리 제품과 함께 고려하는 경쟁사를 추가하면 답변 내 점유율을 비교할 수 있어요." action={<Button onClick={onAdd}><Plus size={13} />경쟁사 추가</Button>} />}</Panel></>; }

function Sources({ metrics }: { metrics: Metrics }) { const [query, setQuery] = useState(""); const sources = metrics.sources.filter(s => `${s.domain} ${s.title}`.toLowerCase().includes(query.toLowerCase())); return <Panel title="AI가 참고한 웹사이트" subtitle="제공자가 답변에 연결한 인용 출처만 집계합니다"><div className="d-toolbar"><div className="d-search-box"><Search size={13} /><input className="d-search-input" value={query} onChange={e => setQuery(e.target.value)} placeholder="도메인 또는 제목 검색" aria-label="인용 출처 검색" /></div><Badge>{metrics.sources.length}개 도메인</Badge></div>{sources.length ? <div className="d-table-wrap"><table className="d-table"><thead><tr><th>출처</th><th>대표 페이지</th><th>인용 수</th><th>비중</th><th /></tr></thead><tbody>{sources.map((source, index) => <tr key={source.domain}><td><div className="d-row-inline"><span className="d-ranking-number">{index + 1}</span><Globe2 size={14} />{source.domain}</div></td><td className="d-td-title">{source.title || source.url}</td><td>{source.citations}</td><td><div className="d-progress-track" style={{ width: 90 }}><div className="d-progress-fill" style={{ width: `${source.citations / Math.max(1, ...metrics.sources.map(s => s.citations)) * 100}%` }} /></div></td><td><a href={safeUrl(source.url)} target="_blank" rel="noopener noreferrer" className="d-icon-button" aria-label={`${source.domain} 원문 열기`}><ExternalLink size={13} /></a></td></tr>)}</tbody></table></div> : <Empty title={query ? "일치하는 출처가 없어요" : "아직 인용된 출처가 없어요"} text="웹 검색 인용이 포함된 답변을 수집하면 참조한 웹사이트와 페이지가 표시됩니다." />}</Panel>; }
function safeUrl(value: string) { try { const u = new URL(value); return ["https:", "http:"].includes(u.protocol) ? u.href : "#"; } catch { return "#"; } }

function Models({ state, answers }: { state: SiteState; answers: Answer[] }) { const models = Array.from(new Set([...(state.site.mode === "demo" ? DEMO_MODELS : state.providers.map(p => p.model)), ...answers.map(a => a.model)])); return <><div className="d-grid-3">{models.map((id, index) => { const metrics = computeMetrics(state.site, state.competitors, latestAnswers(answers.filter(a => a.model === id), state.runs.filter(r => answers.some(a => a.runId === r.id && a.model === id))), state.prompts); const provider = state.providers.find(p => p.model === id); return <Panel className="d-model-card" key={id}><div className="d-card-body"><span className="d-model-logo" style={{ color: colors[index] }}><Bot size={25} strokeWidth={1.4} /></span><h3>{modelName(id)}</h3><Badge tone={state.site.mode === "demo" || (provider?.configured && provider.available) ? "green" : "amber"}>{state.site.mode === "demo" ? "샘플 데이터" : provider?.configured && provider.available ? "API 연결됨" : "API 연결 필요"}</Badge><p>{state.site.mode === "demo" ? "제품 체험을 위한 합성 답변입니다. 해당 서비스의 실제 응답이 아닙니다." : provider?.description || "제공자 API의 답변입니다. 소비자 서비스의 답변과 다를 수 있습니다."}</p><div className="d-model-stat"><span>완료 답변</span><strong>{metrics.answerCount}개</strong></div><div className="d-model-stat"><span>브랜드 언급률</span><strong>{metrics.answerCount ? `${numberLabel(metrics.mentionRate)}%` : "—"}</strong></div><div className="d-model-stat"><span>브랜드 인용률</span><strong>{id === "gemini-3.8-flash" ? "인용 미제공" : metrics.answerCount ? `${numberLabel(metrics.citationRate)}%` : "—"}</strong></div></div></Panel>; })}</div>{state.site.mode !== "demo" && <div className="d-rich-note d-section-space"><ShieldCheck size={15} /><span>OpenAI와 Perplexity는 웹 검색을 사용하고, Gemini는 웹 검색을 사용하지 않는 일반 응답으로 인용을 제공하지 않습니다. 같은 조건의 결과를 비교하려면 모델 필터를 사용하세요. 각 API 답변은 소비자 서비스의 답변과 다를 수 있습니다.</span></div>}<RunHistory runs={state.runs} /></>; }

function Personas({ state, onAdd, onDelete, onUse, busy }: { state: SiteState; onAdd: () => void; onDelete: (p: Persona) => void; onUse: (p: Persona) => void; busy: boolean }) { return state.personas?.length ? <div className="d-grid-3">{state.personas.map(persona => <Panel className="d-persona-card" key={persona.id}><div className="d-card-body"><div className="d-row-inline" style={{ justifyContent: "space-between" }}><span className="d-persona-icon"><Users size={17} /></span><button className="d-icon-button" aria-label="페르소나 삭제" onClick={() => onDelete(persona)}><Trash2 size={13} /></button></div><h3>{persona.name}</h3><p>{persona.description}</p><blockquote>{persona.promptPrefix}</blockquote><Button onClick={() => onUse(persona)} busy={busy}><Plus size={12} />이 관점으로 질문 3개 생성</Button></div></Panel>)}</div> : <Panel><Empty icon={<Users size={24} strokeWidth={1.4} />} title="고객의 관점에서 시작해 보세요" text="고객이 누구인지, 어떤 문제를 해결하려는지 정의하면 더 구체적인 질문을 만들 수 있어요." action={<Button variant="primary" onClick={onAdd}><Plus size={13} />페르소나 만들기</Button>} /></Panel>; }

function Documents({ documents, kind, onOpen, onCreate }: { documents: SavedDocument[]; kind: "content" | "report"; onOpen: (d: SavedDocument) => void; onCreate: () => void }) { return <><div className="d-rich-note"><BookOpen size={15} /><span>{kind === "content" ? "완료된 답변과 브랜드 정보를 참고해 초안을 작성합니다. 게시 전 사실관계와 인용을 검토하고 브랜드의 실제 경험을 더해 주세요." : "선택한 워크스페이스의 실제 수집 결과를 요약합니다. 샘플 워크스페이스에서 생성한 리포트에는 샘플 표시가 포함됩니다."}</span></div><Panel title={kind === "content" ? "내 콘텐츠" : "저장된 리포트"} subtitle={`${documents.length}개 문서`}>{documents.length ? documents.map(doc => <div className="d-document-row" key={doc.id}><span className="d-document-icon">{kind === "content" ? <FileText size={19} strokeWidth={1.4} /> : <BarChart3 size={19} strokeWidth={1.4} />}</span><div className="d-document-info"><h3>{doc.title}</h3><p>{dateLabel(doc.createdAt)} 생성 · {doc.format || "Markdown"} · {doc.mode === "demo" ? "샘플" : "AI 생성 초안"}</p></div><Button onClick={() => onOpen(doc)}><Pencil size={12} />열기</Button><button className="d-icon-button" aria-label="문서 다운로드" onClick={() => downloadFile(`${doc.title.replaceAll("/", "-")}.md`, doc.content, "text/markdown;charset=utf-8")}><ArrowDownToLine size={15} /></button></div>) : <Empty icon={<FileText size={25} strokeWidth={1.3} />} title={kind === "content" ? "첫 콘텐츠를 시작해 보세요" : "데이터를 한 편의 리포트로"} text={kind === "content" ? "질문의 의도와 AI 답변을 바탕으로 브랜드 콘텐츠의 출발점을 만들어보세요." : "브랜드의 현재 위치와 다음 기회를 문서로 정리할 수 있어요."} action={<Button onClick={onCreate} variant="primary"><Sparkles size={13} />{kind === "content" ? "콘텐츠 만들기" : "리포트 생성"}</Button>} />}</Panel></>; }

function Actions({ tasks, onStatus, onEdit, onDelete, onAdd }: { tasks: Task[]; onStatus: (t: Task, s: string) => void; onEdit: (t: Task) => void; onDelete: (t: Task) => void; onAdd: () => void }) { const statuses = { todo: "시작 전", in_progress: "진행 중", done: "완료" }; return <><div className="d-grid-3">{Object.entries(statuses).map(([status, label]) => <section className="d-kanban-column" key={status}><div className="d-kanban-title"><span className="d-legend-dot" style={{ background: status === "done" ? "#6d9f7b" : status === "in_progress" ? "#d7b76c" : "#a7b4ab" }} />{label}<span>{tasks.filter(t => t.status === status).length}</span></div>{tasks.filter(t => t.status === status).map(task => <article className="d-task-card" key={task.id}><div className="d-row-inline" style={{ justifyContent: "space-between" }}><Badge tone={task.priority === "high" ? "amber" : task.priority === "medium" ? "purple" : "gray"}>{task.priority === "high" ? "높은 우선순위" : task.priority === "medium" ? "보통" : "낮음"}</Badge><button className="d-icon-button" onClick={() => onEdit(task)} aria-label="작업 편집"><Pencil size={12} /></button></div><h3>{task.title}</h3><p>{task.description}</p><div className="d-row-inline" style={{ justifyContent: "space-between" }}><select aria-label={`${task.title} 상태`} value={task.status} onChange={e => onStatus(task, e.target.value)}>{Object.entries(statuses).map(([key, name]) => <option value={key} key={key}>{name}</option>)}</select><button className="d-icon-button" onClick={() => onDelete(task)} aria-label="작업 삭제"><Trash2 size={12} /></button></div></article>)}{status === "todo" && <Button variant="quiet" onClick={onAdd} style={{ width: "100%" }}><Plus size={13} />작업 추가</Button>}</section>)}</div>{!tasks.length && <div className="d-rich-note d-section-space"><Sparkles size={15} /><span>답변에서 부족한 설명을 발견했나요? 콘텐츠 보완, 출처 확보, 페이지 개선처럼 직접 실행할 수 있는 작업으로 기록해 보세요.</span></div>}</>; }

function Traffic({ state, flash }: { state: SiteState; flash: (s: string) => void }) { const origin = useSyncExternalStore(subscribeOrigin, () => window.location.origin, () => ""); const script = `<script defer src="${origin}/api/track.js?key=${state.site.trackingKey}"></script>`; return <><div className="d-tracking-stats"><Panel className="d-mini-stat"><span>수집된 전체 방문</span><strong>{numberLabel(state.traffic.totalVisits)}</strong></Panel><Panel className="d-mini-stat"><span>식별된 AI 추천 방문</span><strong>{numberLabel(state.traffic.aiVisits)}</strong></Panel><Panel className="d-mini-stat"><span>AI 추천 방문 비중</span><strong>{state.traffic.totalVisits ? `${numberLabel(state.traffic.aiVisits / state.traffic.totalVisits * 100)}%` : "—"}</strong></Panel></div><Panel title="AI 추천 방문 추이" subtitle={state.site.mode === "demo" ? "샘플 데이터입니다. 실제 방문을 수집한 결과가 아닙니다" : "실제 수집된 방문 이벤트만 표시합니다"}>{state.traffic.totalVisits ? <TrendChart label="AI 추천 방문" suffix="" data={state.traffic.series.map(s => ({ date: s.date, value: s.aiVisits }))} /> : <Empty icon={<TrendingUp size={25} strokeWidth={1.4} />} title="아직 수집된 방문이 없어요" text="웹사이트에 아래 스크립트를 설치하면 방문 데이터를 수집할 수 있어요. 브라우저가 전달한 추천 출처를 기준으로 AI 유입을 식별합니다." />}</Panel><Panel className="d-section-space" title="웹사이트 연결" subtitle={`${state.site.domain}의 페이지에 추적 스크립트를 추가하세요`} action={<Badge tone={state.site.mode === "demo" ? "gray" : state.traffic.totalVisits > 0 ? "green" : "gray"}>{state.site.mode === "demo" ? "샘플 데이터" : state.traffic.totalVisits > 0 ? "이벤트 수신됨" : "이벤트 대기"}</Badge>}><div className="d-card-body"><div className="d-rich-note"><Info size={15} /><span>{state.traffic.note || "추천 정보가 전달되지 않는 방문은 AI 유입으로 분류할 수 없습니다."} 비공개 배포에서는 외부 사이트의 이벤트 전송이 제한될 수 있으며, 공개된 수집 엔드포인트가 필요합니다.</span></div><pre className="d-code">{state.site.mode === "demo" ? "실제 브랜드 워크스페이스를 만들면 추적 스크립트가 제공됩니다." : script}</pre><Button disabled={state.site.mode === "demo"} onClick={async () => { try { await navigator.clipboard.writeText(script); flash("추적 스크립트를 복사했어요"); } catch { flash("브라우저에서 복사를 허용해 주세요"); } }}><Copy size={12} />스크립트 복사</Button></div></Panel><div className="d-grid-2 d-section-space"><Panel title="추천 출처"><div className="d-card-body">{state.traffic.sources.length ? state.traffic.sources.map(s => <div className="d-stat-pair" key={s.source}><span>{s.source}</span><strong>{s.visits}회</strong></div>) : <p className="d-muted">수집된 출처가 없습니다.</p>}</div></Panel><Panel title="방문한 페이지"><div className="d-card-body">{state.traffic.pages.length ? state.traffic.pages.map(s => <div className="d-stat-pair" key={s.path}><span>{s.path}</span><strong>{s.visits}회</strong></div>) : <p className="d-muted">수집된 페이지가 없습니다.</p>}</div></Panel></div></>; }

function Settings({ state, user, onEdit, onDelete }: { state: SiteState; user: { name: string; email: string }; onEdit: () => void; onDelete: () => void }) { return <div className="d-settings-grid"><div><Panel title="브랜드 정보" subtitle="질문과 콘텐츠 생성의 기준이 됩니다" action={<Button onClick={onEdit}><Pencil size={12} />편집</Button>}><div className="d-card-body">{[["브랜드", state.site.name], ["웹사이트", state.site.domain], ["제품 분야", state.site.industry || "미설정"], ["언어", ({ ko: "한국어", en: "English", ja: "日本語" } as Record<string, string>)[state.site.language] || state.site.language], ["국가", ({ KR: "대한민국", US: "미국", JP: "일본", GB: "영국" } as Record<string, string>)[state.site.country] || state.site.country], ["설명", state.site.description || "미설정"]].map(([name, value]) => <div className="d-setting-row" key={name}><strong style={{ minWidth: 65 }}>{name}</strong><p style={{ maxWidth: 280, textAlign: "right", lineHeight: 1.8 }}>{value}</p></div>)}</div></Panel><Panel title="워크스페이스 관리" className="d-section-space"><div className="d-card-body"><div className="d-setting-row"><div><strong>소유자</strong><p>{user.email}</p></div><Badge tone="green">ChatGPT 인증</Badge></div><div className="d-setting-row"><div><strong>워크스페이스 삭제</strong><p>수집된 답변과 문서를 포함한 모든 데이터가 삭제됩니다.</p></div><Button variant="danger" onClick={onDelete}>삭제</Button></div></div></Panel></div><div><Panel title="AI 제공자 연결" subtitle="서버에서 안전하게 관리되는 연결 상태"><div className="d-card-body">{state.providers.map(provider => <div className="d-setting-row" key={provider.id}><div><strong>{provider.name}</strong><p>{provider.description}</p><span className="d-run-table-code">{provider.model}</span></div><Badge tone={provider.configured && provider.available ? "green" : "amber"}>{provider.configured && provider.available ? "연결됨" : "설정 필요"}</Badge></div>)}<div className="d-rich-note" style={{ marginTop: 20, marginBottom: 0 }}><ShieldCheck size={15} /><span>비밀 키는 브라우저에 전달하지 않습니다. 제공자 설정은 배포 환경의 서버 비밀 설정에서 관리합니다.</span></div></div></Panel><Panel title="지표를 읽는 방법" className="d-section-space"><div className="d-card-body"><div className="d-setting-row"><div><strong>언급률과 인용률</strong><p>언급은 답변 본문, 인용은 제공자의 출처 표시를 기준으로 계산합니다.</p></div></div><div className="d-setting-row"><div><strong>분석 기준</strong><p>요약 지표는 선택 기간의 최근 완료 수집 기준입니다. 추이에는 기간 내 완료 답변이 반영됩니다.</p></div></div><div className="d-setting-row"><div><strong>표본의 한계</strong><p>AI 답변은 질문, 수집 시점, 모델에 따라 달라집니다. 이 지표가 실제 구매나 검색량을 뜻하지는 않습니다.</p></div></div></div></Panel></div></div>; }

function Assistant({ siteId, siteName, demo }: { siteId: string; siteName: string; demo: boolean }) { const [messages, setMessages] = useState<{ role: "user" | "assistant"; text: string; citations?: { url: string; title?: string }[] }[]>([]); const [input, setInput] = useState(""); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const bottom = useRef<HTMLDivElement>(null); useEffect(() => { if (messages.length) bottom.current?.scrollIntoView({ behavior: "smooth", block: "nearest" }); }, [messages]); async function send(text: string) { if (!text.trim() || busy) return; setInput(""); setError(""); setMessages(m => [...m, { role: "user", text }]); setBusy(true); try { const result = await api<{ message: string; citations?: { url: string; title?: string }[] }>(`/api/sites/${siteId}/assistant`, "POST", { message: text }); setMessages(m => [...m, { role: "assistant", text: result.message, citations: result.citations }]); } catch (e) { setError((e as Error).message); setInput(text); } finally { setBusy(false); } } return <Panel className="d-assistant">{!messages.length ? <div className="d-assistant-start"><span className="d-assistant-orb"><Sparkles size={27} strokeWidth={1.4} /></span><h2>{siteName}의 다음 기회를 함께 찾아요.</h2><p>이 워크스페이스에서 수집한 답변과 브랜드 정보를<br />참고해 질문에 답합니다.{demo && " 현재는 샘플 모드입니다."}</p><div className="d-assistant-suggestions">{["지금 가장 먼저 개선할 점은 무엇인가요?", "경쟁사와 비교해 부족한 부분을 알려주세요", "다음에 만들 콘텐츠를 제안해 주세요"].map(s => <button key={s} onClick={() => send(s)}>{s}<ArrowUpRight size={11} style={{ display: "inline", marginLeft: 5 }} /></button>)}</div></div> : <div className="d-assistant-messages" aria-live="polite">{messages.map((message, i) => <div key={i} className={`d-message d-message-${message.role}`}>{message.role === "assistant" && <strong>✳ Lumen 어시스턴트</strong>}{message.text}{message.citations?.length ? <div className="d-citations">{message.citations.map((c, j) => <div className="d-citation" key={j}><span>{j + 1}</span><a href={safeUrl(c.url)} target="_blank" rel="noopener noreferrer">{c.title || c.url}</a><ExternalLink size={11} /></div>)}</div> : null}</div>)}{busy && <div className="d-message d-message-assistant d-row-inline"><Loader2 size={14} className="d-spin" />워크스페이스 데이터를 살펴보고 있어요…</div>}<div ref={bottom} /></div>}{error && <div className="d-error" style={{ margin: "0 24px 15px" }} role="alert">{error}</div>}<form className="d-assistant-input" onSubmit={e => { e.preventDefault(); send(input); }}><textarea value={input} onChange={e => setInput(e.target.value)} placeholder="브랜드의 AI 가시성에 대해 무엇이든 물어보세요…" aria-label="어시스턴트 메시지" onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(input); } }} /><Button type="submit" variant="primary" busy={busy} disabled={!input.trim()} aria-label="메시지 보내기"><Send size={15} /></Button></form></Panel>; }

function PromptDetail({ prompt, state, onClose }: { prompt: Prompt; state: SiteState; onClose: () => void }) { const answers = state.answers.filter(a => a.promptId === prompt.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt)); const [selectedId, setSelectedId] = useState(answers[0]?.id || ""); const answer = answers.find(a => a.id === selectedId); const mention = answer ? ownMention(answer, state.site) : null; return <Modal title="질문과 답변" subtitle={prompt.text} onClose={onClose} wide><div className="d-modal-content">{answers.length ? <><Field label="수집된 답변"><select value={selectedId} onChange={e => setSelectedId(e.target.value)}>{answers.map(a => <option value={a.id} key={a.id}>{modelName(a.model)} — {new Date(a.createdAt).toLocaleString("ko-KR")} — {a.status === "completed" ? "완료" : a.status === "failed" ? "실패" : "대기"}</option>)}</select></Field>{answer && <><div className="d-answer-meta"><Badge tone="green">{modelName(answer.model)}</Badge><Badge>{answer.mode === "demo" ? "샘플 답변" : "실제 API 답변"}</Badge><span className="d-muted" style={{ fontSize: 10 }}>{new Date(answer.createdAt).toLocaleString("ko-KR")}</span><Button onClick={() => downloadFile(`answer-${answer.id}.txt`, answer.text)}><ArrowDownToLine size={11} />원문 저장</Button></div>{answer.status === "completed" ? <><div className="d-details-grid"><div className="d-detail-stat"><span>우리 브랜드 언급</span><strong>{mention?.mentioned ? "있음" : "없음"}</strong></div><div className="d-detail-stat"><span>우리 도메인 인용</span><strong>{mention?.cited ? "있음" : "없음"}</strong></div></div><div className="d-answer">{answer.text}</div><div className="d-citations"><h3>{answer.model === "gemini-3.8-flash" ? "웹 검색 미사용 · 인용 미제공" : `인용된 출처 ${answer.citations.length}개`}</h3>{answer.citations.length ? answer.citations.map((citation, i) => <div className="d-citation" key={`${citation.url}-${i}`}><span>{i + 1}</span><a href={safeUrl(citation.url)} target="_blank" rel="noopener noreferrer">{citation.title || citation.url}</a><ExternalLink size={12} />{citation.provenance === "synthetic" && <Badge>샘플</Badge>}</div>) : <p className="d-muted" style={{ fontSize: 11 }}>{answer.model === "gemini-3.8-flash" ? "이 모델은 일반 생성 응답으로 수집하며, 실시간 웹 정보나 검색 인용을 제공하지 않습니다." : "제공자가 표시한 인용 출처가 없습니다."}</p>}</div></> : <Empty title={answer.status === "failed" ? "이 답변을 수집하지 못했어요" : "수집 대기 중입니다"} text={answer.error || "상단의 이어서 수집 버튼으로 완료할 수 있어요."} />}</>}</> : <Empty title="아직 답변이 없어요" text="이 질문의 추적을 활성화한 뒤 답변 수집을 실행해 주세요." />}</div></Modal>; }

function DocumentEditor({ document, onSave, onClose }: { document: SavedDocument; onSave: (text: string) => Promise<void>; onClose: () => void }) { const [text, setText] = useState(document.content); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); return <Modal title={document.title} subtitle={`${document.mode === "demo" ? "샘플 문서" : "AI 생성 초안"} · Markdown 형식으로 편집하고 내보낼 수 있어요.`} onClose={onClose} wide><div className="d-modal-content"><textarea className="d-editor" aria-label="문서 내용 편집" value={text} onChange={e => setText(e.target.value)} />{error && <p className="d-error">{error}</p>}<div className="d-form-actions"><Button onClick={() => downloadFile(`${document.title.replaceAll("/", "-")}.md`, text, "text/markdown;charset=utf-8")}><ArrowDownToLine size={13} />Markdown 다운로드</Button><Button variant="primary" busy={busy} onClick={async () => { setBusy(true); try { await onSave(text); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }}><Check size={13} />저장</Button></div></div></Modal>; }

function ProductForm({ kind, edit, busy, onClose, onSubmit, demo }: { kind: FormKind; edit: EditItem | null; busy: boolean; onClose: () => void; onSubmit: (values: Record<string, unknown>) => Promise<void>; demo?: boolean }) {
  const titles = { site: "브랜드 워크스페이스", prompt: "추적할 질문", competitor: "경쟁 브랜드", content: "콘텐츠 초안", report: "분석 리포트", task: "실행 작업", persona: "고객 페르소나" }; const initial = (key: string, fallback = "") => String((edit as unknown as Record<string, unknown>)?.[key] ?? fallback); const [error, setError] = useState("");
  async function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const data = Object.fromEntries(new FormData(e.currentTarget)); const values: Record<string, unknown> = { ...data }; if (kind === "prompt") { values.active = data.active === "on"; if (!values.topic) values.topic = "일반"; } setError(""); try { await onSubmit(values); } catch (e) { setError((e as Error).message); } }
  return <Modal title={`${titles[kind]} ${edit ? "편집" : kind === "content" || kind === "report" ? "만들기" : "추가"}`} subtitle={kind === "site" ? "브랜드 이름과 설명은 AI 질문 및 콘텐츠 생성에 사용됩니다." : kind === "prompt" ? "고객이 AI에 직접 물어볼 만한 구체적인 질문을 작성하세요." : kind === "content" || kind === "report" ? demo ? "샘플 데이터로 예시 문서를 생성합니다." : "수집된 답변을 참고해 작성합니다. 생성에 잠시 시간이 걸릴 수 있어요." : undefined} onClose={onClose}><form className="d-form" onSubmit={submit}>
    {kind === "site" && <><Field label="브랜드 이름"><input name="name" required minLength={2} maxLength={100} placeholder="예: Atelier" defaultValue={initial("name")} /></Field><Field label="웹사이트 도메인"><input name="domain" required maxLength={200} placeholder="예: atelier.so" defaultValue={initial("domain")} autoCapitalize="none" /></Field><Field label="어떤 제품인가요?"><textarea name="description" required maxLength={2000} placeholder="제품이 해결하는 문제, 주요 고객, 차별점을 설명해 주세요." defaultValue={initial("description")} /></Field><Field label="제품 분야"><input name="industry" maxLength={100} placeholder="예: 프로젝트 관리 소프트웨어" defaultValue={initial("industry")} /></Field><div className="d-form-row"><Field label="답변 언어"><select name="language" defaultValue={({ ko: "한국어", en: "English", ja: "日本語" } as Record<string, string>)[initial("language")] || initial("language", "한국어")}><option value="한국어">한국어</option><option value="English">English</option><option value="日本語">日本語</option></select></Field><Field label="대상 국가"><select name="country" defaultValue={initial("country", "KR")}><option value="KR">대한민국</option><option value="US">미국</option><option value="JP">일본</option><option value="GB">영국</option></select></Field></div></>}
    {kind === "prompt" && <><Field label="고객의 질문"><textarea name="text" required minLength={5} maxLength={1000} placeholder="예: 작은 디자인 팀에 적합한 프로젝트 관리 도구를 추천해 주세요." defaultValue={initial("text")} /></Field><div className="d-form-row"><Field label="주제"><input name="topic" maxLength={80} placeholder="예: 팀 협업" defaultValue={initial("topic")} /></Field><Field label="검색 의도"><select name="intent" defaultValue={initial("intent", "comparison")}>{Object.entries(intentNames).map(([key, name]) => <option value={key} key={key}>{name}</option>)}</select></Field></div><label className="d-checkbox-label"><input name="active" type="checkbox" defaultChecked={edit ? (edit as Prompt).active : true} />다음 답변 수집에 포함</label></>}
    {kind === "competitor" && <><Field label="브랜드 이름"><input name="name" required minLength={2} maxLength={100} placeholder="비교할 브랜드 이름" defaultValue={initial("name")} /></Field><Field label="웹사이트 도메인"><input name="domain" required maxLength={200} placeholder="예: example.com" defaultValue={initial("domain")} autoCapitalize="none" /></Field></>}
    {(kind === "content" || kind === "report") && <><Field label={kind === "content" ? "작성할 주제" : "리포트의 초점"}><textarea name="topic" required minLength={3} maxLength={500} placeholder={kind === "content" ? "예: 디자인 팀이 협업 도구를 선택할 때 확인할 5가지 기준" : "예: 현재 브랜드 가시성과 경쟁사 비교, 우선 개선할 콘텐츠"} /></Field><Field label="문서 형식"><select name="format" defaultValue={kind === "report" ? "report" : "article"}>{kind === "content" ? <><option value="article">블로그 아티클</option><option value="faq">질문과 답변 (FAQ)</option><option value="comparison">비교 가이드</option><option value="how-to">활용 가이드</option><option value="listicle">목록형 콘텐츠</option></> : <><option value="report">성과 분석 리포트</option></>}</select></Field></>}
    {kind === "task" && <><Field label="작업 이름"><input name="title" required minLength={3} maxLength={200} placeholder="예: 제품 비교 페이지에 실제 사용 사례 추가" defaultValue={initial("title")} /></Field><Field label="작업 설명"><textarea name="description" maxLength={2000} placeholder="왜 필요한지, 무엇을 완료하면 되는지 기록하세요." defaultValue={initial("description")} /></Field><div className="d-form-row"><Field label="우선순위"><select name="priority" defaultValue={initial("priority", "medium")}><option value="high">높음</option><option value="medium">보통</option><option value="low">낮음</option></select></Field><Field label="상태"><select name="status" defaultValue={initial("status", "todo")}><option value="todo">시작 전</option><option value="in_progress">진행 중</option><option value="done">완료</option></select></Field></div></>}
    {kind === "persona" && <><Field label="페르소나 이름"><input name="name" required minLength={2} maxLength={100} placeholder="예: 10인 규모 디자인 팀 리더" defaultValue={initial("name")} /></Field><Field label="고객의 상황과 필요"><textarea name="description" required maxLength={1000} placeholder="현재 겪고 있는 문제와 제품 선택 시 중요하게 생각하는 기준" defaultValue={initial("description")} /></Field><Field label="질문에 붙일 맥락" hint="이 문장을 앞에 붙여 페르소나의 관점에서 질문을 만듭니다."><textarea name="promptPrefix" required maxLength={500} placeholder="저는 10명으로 구성된 디자인 팀의 리더이고, 프로젝트 현황을 한눈에 관리할 도구를 찾고 있습니다." defaultValue={initial("promptPrefix")} /></Field></>}
    {error && <div className="d-error" role="alert" style={{ marginTop: 15 }}>{error}</div>}<div className="d-form-actions"><Button type="button" onClick={onClose} disabled={busy}>취소</Button><Button type="submit" variant="primary" busy={busy}>{kind === "content" || kind === "report" ? "생성하기" : edit ? "저장하기" : "추가하기"}{!busy && <ArrowRight size={12} />}</Button></div>
  </form></Modal>;
}
